import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, Optional

from openai import OpenAI

OPENAI_BATCH_API_KEY_ENV = "OPENAI_API_KEY"
OPENAI_BATCH_BASE_URL = "https://api.openai.com/v1"
OPENAI_BATCH_MODEL = "gpt-4o-mini-transcribe"
OPENAI_BATCH_ENDPOINT = "/v1/audio/transcriptions"


@dataclass(frozen=True)
class BatchSpeechConfig:
    api_key: str
    base_url: str = OPENAI_BATCH_BASE_URL
    model: str = OPENAI_BATCH_MODEL


def load_batch_speech_config() -> BatchSpeechConfig:
    api_key = os.getenv(OPENAI_BATCH_API_KEY_ENV)
    if not api_key:
        raise RuntimeError(f"{OPENAI_BATCH_API_KEY_ENV} is required")
    return BatchSpeechConfig(api_key=api_key)


def create_batch_speech_client(config: Optional[BatchSpeechConfig] = None) -> OpenAI:
    cfg = config or load_batch_speech_config()
    return OpenAI(api_key=cfg.api_key, base_url=cfg.base_url)


def transcribe_audio_file(
    audio_path: str | Path,
    *,
    timestamp_granularities: Optional[Iterable[str]] = None,
    response_format: str = "verbose_json",
    model: Optional[str] = None,
    config: Optional[BatchSpeechConfig] = None,
) -> Dict[str, Any]:
    cfg = config or load_batch_speech_config()
    client = create_batch_speech_client(cfg)
    with Path(audio_path).open("rb") as audio_file:
        response = client.audio.transcriptions.create(
            model=model or cfg.model,
            file=audio_file,
            response_format=response_format,
            timestamp_granularities=list(timestamp_granularities) if timestamp_granularities is not None else ["word", "segment"],
        )
    if hasattr(response, "model_dump"):
        return response.model_dump()
    return dict(response)


def extract_transcript(result: Dict[str, Any]) -> str:
    if "text" in result and isinstance(result["text"], str):
        return result["text"]
    if "transcript" in result and isinstance(result["transcript"], str):
        return result["transcript"]
    response = result.get("response")
    if isinstance(response, dict):
        body = response.get("body")
        if isinstance(body, dict):
            text = body.get("text")
            if isinstance(text, str):
                return text
            transcript = body.get("transcript")
            if isinstance(transcript, str):
                return transcript
    return ""


def get_timestamps(result: Dict[str, Any]) -> Dict[str, list[Dict[str, Any]]]:
    return {"words": list(result.get("words") or []), "segments": list(result.get("segments") or [])}

import argparse
import json
import os
import sys
import time

import requests


OPENAI_BATCHES_ENDPOINT = "https://api.openai.com/v1/batches/"


def get_batch(batch_id: str, api_key: str) -> dict:
    response = requests.get(
        f"{OPENAI_BATCHES_ENDPOINT}{batch_id}",
        headers={"Authorization": f"Bearer {api_key}"},
        timeout=120,
    )
    response.raise_for_status()
    return response.json()


def get_result_file(file_id: str, api_key: str) -> str:
    response = requests.get(
        f"https://api.openai.com/v1/files/{file_id}/content",
        headers={"Authorization": f"Bearer {api_key}"},
        timeout=120,
    )
    response.raise_for_status()
    return response.text


def extract_transcript(batch: dict, api_key: str) -> str | None:
    output_file_id = batch.get("output_file_id")
    if not output_file_id:
        return None
    content = get_result_file(output_file_id, api_key)
    try:
        payload = json.loads(content)
    except json.JSONDecodeError:
        return content
    if isinstance(payload, dict):
        if "response" in payload and isinstance(payload["response"], dict):
            response = payload["response"]
            if "body" in response and isinstance(response["body"], dict):
                body = response["body"]
                if "text" in body:
                    return body["text"]
                if "transcript" in body:
                    return body["transcript"]
        if "text" in payload:
            return payload["text"]
        if "transcript" in payload:
            return payload["transcript"]
    return content


def main() -> int:
    parser = argparse.ArgumentParser(description="Poll an OpenAI transcription batch until completion and print the transcript.")
    parser.add_argument("batch_id", help="OpenAI batch ID to poll")
    parser.add_argument("--interval", type=float, default=5.0, help="Polling interval in seconds")
    parser.add_argument("--timeout", type=float, default=3600.0, help="Maximum polling time in seconds")
    args = parser.parse_args()

    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("OPENAI_API_KEY is required", file=sys.stderr)
        return 1

    deadline = time.time() + args.timeout
    while True:
        batch = get_batch(args.batch_id, api_key)
        status = batch.get("status")
        if status == "completed":
            transcript = extract_transcript(batch, api_key)
            if transcript is None:
                print("Batch completed without an output file", file=sys.stderr)
                return 1
            print(transcript)
            return 0
        if status in {"failed", "cancelled", "expired"}:
            print(json.dumps(batch, indent=2, sort_keys=True), file=sys.stderr)
            return 1
        if time.time() >= deadline:
            print("Polling timed out", file=sys.stderr)
            return 1
        time.sleep(args.interval)


if __name__ == "__main__":
    raise SystemExit(main())

